changed=[]
for module,pairs in pairs_by_module.items():
 for p in sorted((root/'Clases_Crecimiento_Economico'/module).rglob('*.Rmd')):
  s=p.read_text(encoding='utf-8-sig');out=s;matches=[]
  for old,new in pairs:
   count=out.count(old)
   if count:out=out.replace(old,new);matches.append({'old':old,'count':count})
  if out!=s:
   assert re.findall(r'```\{r.*?```',s,re.S)==re.findall(r'```\{r.*?```',out,re.S)
   assert re.findall(r'(?:readPNG|readJPEG)\([^\n]+|<img[^>]+>',s)==re.findall(r'(?:readPNG|readJPEG)\([^\n]+|<img[^>]+>',out)
   p.write_text(out,encoding='utf-8',newline='\n');changed.append({'path':p.relative_to(root).as_posix(),'changes':matches,'sha256_after':hashlib.sha256(out.encode()).hexdigest()})
